Rules.InvariantScript:
ClearCollect(
    AllRecords,
    FirstN(
        SortByColumns('Coverage Request (Belgium)', "Created", SortOrder.Descending),
        2000
    )
);


ClearCollect(
    FilterOptions,
    {Name: "Future Coverage", FilterFunction: "Future"},
    {Name: "Last 2 Months Submissions", FilterFunction: "Last2Months"},
    {Name: "Both", FilterFunction: "Both"},
    {Name: "none", FilterFunction: "none"}
);

If(
    CountRows(FutureCoveragesGallery.AllItems) > 0,
    Select(FutureCoveragesGallery,1)
);

With(
    {
        totalMinutes: DateDiff(
        ThisItem.'Start Date and Time',
        ThisItem.'End Date and Time',
        TimeUnit.Minutes
        )
    },

  Text(
            Int(totalMinutes / 1440) & " days, " & Char(10) &
            Int(Mod(totalMinutes, 1440) / 60) & " hours, " & Char(10) &
            Mod(totalMinutes, 60) & " minutes"
        ) 
)

Set(
    currentSubmission,
    LookUp('Coverage Request (Belgium)', ID = ThisItem.ID)
);

Set(ResetCheckboxes, true);
Set(ResetCheckboxes, false);

Set(varEventTypes, Blank());
Set(otherEventValue, Blank());
Set(VIPEventValue, Blank());

Set(VideoCoverageSelected, false);
Set(OnlyBilateralOtherVIPSelected, false);
Set(varEventCoverageType, Blank());
Set(varWebstreamed, Blank());
Set(varWebstreamedOrganizer, Blank());
Reset(CoverageTypeRadio);
Reset(WebstreamedRadio);
Reset(WebstreamedOrganizerText);

Set(varCarbonCopyContactsString, Blank());
Set(varCarbonCopyContactsArray, Blank());
Set(varCarbonCopyContactsFormattedArray, Table());
Reset(CarbonCopyContactComboBox);

ResetForm(CoverageFormRequest);
NewForm(CoverageFormRequest);

Set(varCollegeMember, currentSubmission.'College Member');
Set(varEventTitle, currentSubmission.'Event Title');

Set(varStartDateTime, currentSubmission.'Start Date and Time');
Set(varStartDate, DateValue(Text(varStartDateTime, "mm-dd-yyyy"), "en-US"));
// Set(varStartHour, Text(If(Mod(Hour(varStartDateTime),12) = 0, 12, Mod(Hour(varStartDateTime), 12)), "[$-en-US]00"));
// Set(varStartAMPM, If(Hour(varStartDateTime) <12, "[$-en-US]AM", "PM"));
Set(varStartHour, Text(Hour(varStartDateTime), "[$-en-US]00")); 
Set(varStartMinute, Text(Minute(varStartDateTime), "00"));

Set(varEndDateTime, currentSubmission.'End Date and Time');
Set(varEndDate, DateValue(Text(varEndDateTime, "mm-dd-yyyy"), "en-US"));
// Set(varEndHour, Text(If(Mod(Hour(varEndDateTime),12) = 0, 12, Mod(Hour(varEndDateTime), 12)), "[$-en-US]00"));
// Set(varEndAMPM, If(Hour(varEndDateTime) <12, "[$-en-US]AM", "PM"));
Set(varEndHour, Text(Hour(varEndDateTime), "[$-en-US]00")); 
Set(varEndMinute, Text(Minute(varEndDateTime), "00"));

Set(varLocation, currentSubmission.Location);
Set(varAddress, currentSubmission.Address);

Set(varEventTypes, currentSubmission.'Event Type');
Set(TypeofEventSelected, EventTypeDropdown.SelectedItems.Value);

Set(matchingOtherItem, First(Filter(varEventTypes, StartsWith(Value, "Other: "))));
If(!IsBlank(matchingOtherItem),
    Set(otherEventValue, Mid(matchingOtherItem.Value, Len("Other :") + 1, Len(matchingOtherItem.Value))),
    Set(otherEventValue, "")
);

Set(matchingVIPItem, First(Filter(varEventTypes, StartsWith(Value, "VIP: "))));
If(!IsBlank(matchingVIPItem),
    Set(VIPEventValue, Mid(matchingVIPItem.Value, Len("VIP:") + 1, Len(matchingVIPItem.Value))),
    Set(VIPEventValue, "")
);

Set(
varEventTypes,
    ForAll(
        varEventTypes,
        Switch(
            true,
            StartsWith(Value, "Other: "), {Value: "Other"},
            StartsWith(Value, "VIP: "), {Value: "Bilateral with other VIP/s"},
            {Value: Value} // Default case
        )
    )
);

Set(varCoverageTypes, currentSubmission.'Coverage Type');
If("Video Coverage" in CoverageTypeDropdown.SelectedItems.Value, Set(VideoCoverageSelected, true));
If("Bilateral with other VIP/s" in varEventTypes.Value && CountRows(varEventTypes) = 1, Set(OnlyBilateralOtherVIPSelected, true));

Set(varEventCoverageType, currentSubmission.'Event Coverage Type');
Set(varWebstreamed, currentSubmission.Webstreamed);
Set(varWebstreamedOrganizer, currentSubmission.'Webstreamed Organizer');

Set(varPublicationType, currentSubmission.'Publication Type');

Set(varContacts, currentSubmission.'Accreditation Info');
Set(varSocialMediaContacts, currentSubmission.'Media Receivers');
Set(varTravelWithCommissionerContacts, currentSubmission.'Accompanying the Commissioner');
Set(varComments, currentSubmission.Comments);

Set(varCarbonCopyContactsString, currentSubmission.'Carbon Copy Contacts');
Set(varCarbonCopyContactsArray, Split(Trim(currentSubmission.'Carbon Copy Contacts'), ";"));

Set(
    varCarbonCopyContactsFormattedArray,
    ForAll(
        varCarbonCopyContactsArray,
        {
            DisplayName: ThisRecord.Value,
            Mail: TrimEnds(ThisRecord.Value)
        }
    )
);

Navigate(FormScreen);

Notify("The form has been filled with your last submission data " 
        & "[ID: " & currentSubmission.ID & "]  [Created on: " & Text(currentSubmission.Created, "dd/mm/yyyy hh:mm AM/PM") & "]", 
    NotificationType.Success);
